contracts/LicenseRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./ProjectRegistry.sol";

/// @title LicenseRegistry
/// @notice Records exactly what a buyer purchased — a LICENSE, not project ownership.
///
/// @dev Core invariants (never violated):
///      1. A license purchase does NOT transfer the project NFT (except FullIPTransfer type).
///      2. Seller cannot purchase their own listing.
///      3. Payment and license record happen atomically.
///      4. Platform fee never exceeds FEE_CAP_BPS (hard-coded).
///      5. Only allowlisted tokens are accepted.
///      6. Fee changes are timelocked (FEE_TIMELOCK_DELAY seconds).
///      7. Allowlist changes are timelocked.
///      8. SafeERC20 used for all token transfers.
///
/// License types (must match ProjectRegistry.LicenseConfig):
///   0 None | 1 Personal | 2 Commercial | 3 Exclusive | 4 SourceAccess | 5 FullIPTransfer
contract LicenseRegistry is AccessControlDefaultAdminRules, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    uint256 public constant FEE_CAP_BPS      = 1000;   // hard ceiling: 10%
    uint48  public constant FEE_TIMELOCK_DELAY = 2 days; // fee/allowlist changes must wait

    bytes32 public constant FEE_MANAGER_ROLE = keccak256("FEE_MANAGER_ROLE");
    bytes32 public constant PAUSER_ROLE      = keccak256("PAUSER_ROLE");

    // -------------------------------------------------------------------------
    // License types — must match spec exactly
    // -------------------------------------------------------------------------

    enum LicenseType {
        None,           // 0 — invalid
        Personal,       // 1
        Commercial,     // 2
        Exclusive,      // 3 — only one can be sold; freezes further commercial sales
        SourceAccess,   // 4 — buyer gets read access to private repo (backend listens to event)
        FullIPTransfer  // 5 — also triggers NFT transfer to buyer
    }

    // -------------------------------------------------------------------------
    // Storage
    // -------------------------------------------------------------------------

    ProjectRegistry public immutable projectRegistry;

    struct Listing {
        address seller;
        address token;        // allowlisted ERC-20 (e.g. USDC)
        uint256 price;
        LicenseType licenseType;
        bool active;
    }

    struct LicenseRecord {
        uint256 projectId;
        address seller;
        address buyer;
        address token;
        uint256 price;
        LicenseType licenseType;
        bytes32 metadataHash;     // hash of off-chain license terms
        uint64  purchasedAt;
        bool    active;
    }

    mapping(uint256 => Listing) public listings;             // projectId => Listing
    mapping(uint256 => LicenseRecord) public licenses;        // licenseId => LicenseRecord
    mapping(uint256 => bool) public exclusiveSold;            // projectId => exclusive sold?

    uint256 private _nextLicenseId;

    // Fee
    uint256 public platformFeeBps = 250;  // 2.5% default

    // Timelock for fee changes
    struct PendingFeeChange {
        uint256 newFeeBps;
        uint64  readyAt;
        bool    pending;
    }
    PendingFeeChange public pendingFee;

    // Token allowlist + timelock
    mapping(address => bool) public allowedTokens;
    struct PendingTokenChange {
        address token;
        bool    adding;
        uint64  readyAt;
        bool    pending;
    }
    PendingTokenChange public pendingTokenChange;

    // Accumulated fees per token (platform pulls via withdrawFees)
    mapping(address => uint256) public accumulatedFees;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event Listed(uint256 indexed projectId, address indexed seller, address token, uint256 price, LicenseType licenseType);
    event Unlisted(uint256 indexed projectId, address indexed seller);
    event LicensePurchased(
        uint256 indexed licenseId,
        uint256 indexed projectId,
        address indexed buyer,
        LicenseType licenseType,
        uint256 price,
        address token
    );
    event FeeBpsProposed(uint256 newFeeBps, uint64 readyAt);
    event FeeBpsApplied(uint256 newFeeBps);
    event TokenChangeProposed(address token, bool adding, uint64 readyAt);
    event TokenChangeApplied(address token, bool added);
    event FeesWithdrawn(address token, address to, uint256 amount);

    // -------------------------------------------------------------------------
    // Errors
    // -------------------------------------------------------------------------

    error TokenNotAllowed();
    error ListingNotActive();
    error CannotBuyOwnListing();
    error ExclusiveAlreadySold();
    error FeeTooHigh();
    error TimelockNotExpired();
    error NoPendingChange();
    error ZeroAddress();
    error ZeroPrice();
    error ProjectNotActive();
    error Unauthorized();
    error NoFeesToWithdraw();

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    constructor(
        address _projectRegistry,
        uint48  adminTransferDelay,
        address initialAdmin
    ) AccessControlDefaultAdminRules(adminTransferDelay, initialAdmin) {
        if (_projectRegistry == address(0)) revert ZeroAddress();
        if (initialAdmin == address(0)) revert ZeroAddress();
        projectRegistry = ProjectRegistry(_projectRegistry);
        _grantRole(FEE_MANAGER_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
    }

    // -------------------------------------------------------------------------
    // Token allowlist (timelocked)
    // -------------------------------------------------------------------------

    function proposeTokenChange(address token, bool adding)
        external onlyRole(FEE_MANAGER_ROLE)
    {
        if (token == address(0)) revert ZeroAddress();
        pendingTokenChange = PendingTokenChange({
            token: token,
            adding: adding,
            readyAt: uint64(block.timestamp) + FEE_TIMELOCK_DELAY,
            pending: true
        });
        emit TokenChangeProposed(token, adding, pendingTokenChange.readyAt);
    }

    function applyTokenChange() external onlyRole(FEE_MANAGER_ROLE) {
        PendingTokenChange memory c = pendingTokenChange;
        if (!c.pending) revert NoPendingChange();
        if (block.timestamp < c.readyAt) revert TimelockNotExpired();
        allowedTokens[c.token] = c.adding;
        delete pendingTokenChange;
        emit TokenChangeApplied(c.token, c.adding);
    }

    // -------------------------------------------------------------------------
    // Fee management (timelocked)
    // -------------------------------------------------------------------------

    function proposeFeeBps(uint256 newFeeBps) external onlyRole(FEE_MANAGER_ROLE) {
        if (newFeeBps > FEE_CAP_BPS) revert FeeTooHigh();
        pendingFee = PendingFeeChange({
            newFeeBps: newFeeBps,
            readyAt: uint64(block.timestamp) + FEE_TIMELOCK_DELAY,
            pending: true
        });
        emit FeeBpsProposed(newFeeBps, pendingFee.readyAt);
    }

    function applyFeeBps() external onlyRole(FEE_MANAGER_ROLE) {
        PendingFeeChange memory f = pendingFee;
        if (!f.pending) revert NoPendingChange();
        if (block.timestamp < f.readyAt) revert TimelockNotExpired();
        platformFeeBps = f.newFeeBps;
        delete pendingFee;
        emit FeeBpsApplied(f.newFeeBps);
    }

    // -------------------------------------------------------------------------
    // Listing
    // -------------------------------------------------------------------------

    function listProject(
        uint256    projectId,
        address    token,
        uint256    price,
        LicenseType licenseType,
        bytes32    metadataHash
    ) external whenNotPaused {
        if (!allowedTokens[token]) revert TokenNotAllowed();
        if (price == 0) revert ZeroPrice();
        if (licenseType == LicenseType.None) revert Unauthorized();
        if (projectRegistry.ownerOf(projectId) != msg.sender) revert Unauthorized();

        (,,,, , bool active,,) = projectRegistry.getProject(projectId);
        if (!active) revert ProjectNotActive();

        // Cannot re-list if exclusive already sold
        if (licenseType == LicenseType.Exclusive && exclusiveSold[projectId]) revert ExclusiveAlreadySold();
        if (licenseType == LicenseType.FullIPTransfer && exclusiveSold[projectId]) revert ExclusiveAlreadySold();

        listings[projectId] = Listing({
            seller: msg.sender,
            token: token,
            price: price,
            licenseType: licenseType,
            active: true
        });

        emit Listed(projectId, msg.sender, token, price, licenseType);
    }

    function cancelListing(uint256 projectId) external whenNotPaused {
        Listing storage l = listings[projectId];
        if (!l.active) revert ListingNotActive();
        if (l.seller != msg.sender) revert Unauthorized();
        delete listings[projectId];
        emit Unlisted(projectId, msg.sender);
    }

    // -------------------------------------------------------------------------
    // Purchase — atomic: payment + license record (+ optional NFT transfer)
    // -------------------------------------------------------------------------

    function purchaseLicense(
        uint256 projectId,
        bytes32 metadataHash  // hash of agreed license terms stored off-chain
    ) external nonReentrant whenNotPaused returns (uint256 licenseId) {
        Listing memory l = listings[projectId];
        if (!l.active) revert ListingNotActive();
        if (msg.sender == l.seller) revert CannotBuyOwnListing();
        if (l.licenseType == LicenseType.Exclusive && exclusiveSold[projectId]) revert ExclusiveAlreadySold();

        uint256 fee            = (l.price * platformFeeBps) / 10_000;
        uint256 sellerProceeds = l.price - fee;

        // ---- Payment (atomic, SafeERC20) ----
        IERC20(l.token).safeTransferFrom(msg.sender, address(this), l.price);
        IERC20(l.token).safeTransfer(l.seller, sellerProceeds);
        accumulatedFees[l.token] += fee;

        // ---- License record ----
        licenseId = _nextLicenseId++;
        licenses[licenseId] = LicenseRecord({
            projectId:   projectId,
            seller:      l.seller,
            buyer:       msg.sender,
            token:       l.token,
            price:       l.price,
            licenseType: l.licenseType,
            metadataHash: metadataHash,
            purchasedAt: uint64(block.timestamp),
            active:      true
        });

        // ---- Post-purchase side-effects ----
        if (l.licenseType == LicenseType.Exclusive) {
            exclusiveSold[projectId] = true;
            delete listings[projectId]; // no more sales of this type
            projectRegistry.freezeMetadata(projectId);
        } else if (l.licenseType == LicenseType.FullIPTransfer) {
            exclusiveSold[projectId] = true;
            delete listings[projectId];
            projectRegistry.freezeMetadata(projectId);
            // NFT transfer: seller must have approved ProjectRegistry.transferProject
            projectRegistry.transferProject(projectId, msg.sender);
        } else {
            // Non-exclusive licenses: listing stays active for further purchases
        }

        emit LicensePurchased(licenseId, projectId, msg.sender, l.licenseType, l.price, l.token);
        // Note: backend listens to this event and grants repo access for SourceAccess licenses.
    }

    // -------------------------------------------------------------------------
    // Fee withdrawal — only to admin, only accumulated fees (not user funds)
    // -------------------------------------------------------------------------

    function withdrawFees(address token, address to) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = accumulatedFees[token];
        if (amount == 0) revert NoFeesToWithdraw();
        accumulatedFees[token] = 0;
        IERC20(token).safeTransfer(to, amount);
        emit FeesWithdrawn(token, to, amount);
    }

    // -------------------------------------------------------------------------
    // Pause
    // -------------------------------------------------------------------------

    function pause()   external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    // -------------------------------------------------------------------------
    // Views
    // -------------------------------------------------------------------------

    function getLicense(uint256 licenseId) external view returns (LicenseRecord memory) {
        return licenses[licenseId];
    }

    function getListing(uint256 projectId) external view returns (Listing memory) {
        return listings[projectId];
    }
}

contracts/LocalWeb3LinkedInEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Minimal local/testnet escrow adapter for the Web3LinkedIn milestone lifecycle.
/// @dev This is intentionally separate from the legacy imported prototype until that contract
/// is reviewed and deployed. It has no upgrade/admin backdoor and guards each payout once.
contract LocalWeb3LinkedInEscrow {
    enum Status {
        Open,
        Hired,
        Submitted,
        Approved,
        Paid,
        Cancelled
    }

    struct Milestone {
        address developer;
        address recruiter;
        uint256 amount;
        Status status;
        bool escrowLocked;
        string title;
        string proofUrl;
        string githubUrl;
        string liveDemoUrl;
        string notes;
    }

    uint256 public nextMilestoneId;
    mapping(uint256 => Milestone) public milestones;
    mapping(address => bool) public frozenProfiles;
    mapping(uint256 => bool) public projectBurned;

    event MilestoneCreated(uint256 indexed milestoneId, address indexed developer, uint256 amount, string title);
    event MilestoneHired(uint256 indexed milestoneId, address indexed recruiter);
    event ProofSubmitted(uint256 indexed milestoneId, string proofUrl, string githubUrl, string liveDemoUrl);
    event WorkApproved(uint256 indexed milestoneId);
    event EscrowReleased(uint256 indexed milestoneId, address indexed developer, uint256 amount);
    event MilestoneCancelled(uint256 indexed milestoneId);
    event ProfileFrozen(address indexed account);
    event ProjectBurned(uint256 indexed projectId);

    modifier developerOnly(uint256 milestoneId) {
        require(msg.sender == milestones[milestoneId].developer, "developer only");
        _;
    }

    modifier recruiterOnly(uint256 milestoneId) {
        require(msg.sender == milestones[milestoneId].recruiter, "recruiter only");
        _;
    }

    function createMilestone(string calldata title, uint256 amount) external returns (uint256 milestoneId) {
        require(amount > 0, "amount required");
        require(!frozenProfiles[msg.sender], "profile frozen");
        milestoneId = nextMilestoneId++;
        milestones[milestoneId] = Milestone({
            developer: msg.sender,
            recruiter: address(0),
            amount: amount,
            status: Status.Open,
            escrowLocked: false,
            title: title,
            proofUrl: "",
            githubUrl: "",
            liveDemoUrl: "",
            notes: ""
        });
        emit MilestoneCreated(milestoneId, msg.sender, amount, title);
    }

    function hire(uint256 milestoneId) external payable {
        Milestone storage milestone = milestones[milestoneId];
        require(milestone.status == Status.Open, "not open");
        require(msg.value == milestone.amount, "exact amount required");
        milestone.recruiter = msg.sender;
        milestone.escrowLocked = true;
        milestone.status = Status.Hired;
        emit MilestoneHired(milestoneId, msg.sender);
    }

    function submitProof(
        uint256 milestoneId,
        string calldata proofUrl,
        string calldata githubUrl,
        string calldata liveDemoUrl,
        string calldata notes
    ) external developerOnly(milestoneId) {
        Milestone storage milestone = milestones[milestoneId];
        require(milestone.status == Status.Hired, "not hired");
        milestone.proofUrl = proofUrl;
        milestone.githubUrl = githubUrl;
        milestone.liveDemoUrl = liveDemoUrl;
        milestone.notes = notes;
        milestone.status = Status.Submitted;
        emit ProofSubmitted(milestoneId, proofUrl, githubUrl, liveDemoUrl);
    }

    function approve(uint256 milestoneId) external recruiterOnly(milestoneId) {
        require(milestones[milestoneId].status == Status.Submitted, "not submitted");
        milestones[milestoneId].status = Status.Approved;
        emit WorkApproved(milestoneId);
    }

    function release(uint256 milestoneId) external recruiterOnly(milestoneId) {
        Milestone storage milestone = milestones[milestoneId];
        require(milestone.status == Status.Approved, "not approved");
        require(milestone.escrowLocked, "escrow already released");
        milestone.escrowLocked = false;
        milestone.status = Status.Paid;
        (bool sent, ) = payable(milestone.developer).call{value: milestone.amount}("");
        require(sent, "payment failed");
        emit EscrowReleased(milestoneId, milestone.developer, milestone.amount);
    }

    function cancel(uint256 milestoneId) external {
        Milestone storage milestone = milestones[milestoneId];
        require(msg.sender == milestone.developer || msg.sender == milestone.recruiter, "not participant");
        require(milestone.status == Status.Open || milestone.status == Status.Hired, "cannot cancel");
        if (milestone.escrowLocked) {
            milestone.escrowLocked = false;
            (bool sent, ) = payable(milestone.recruiter).call{value: milestone.amount}("");
            require(sent, "refund failed");
        }
        milestone.status = Status.Cancelled;
        emit MilestoneCancelled(milestoneId);
    }

    function freezeProfile() external {
        frozenProfiles[msg.sender] = true;
        emit ProfileFrozen(msg.sender);
    }

    function burnProject(uint256 projectId) external {
        require(!projectBurned[projectId], "already burned");
        projectBurned[projectId] = true;
        emit ProjectBurned(projectId);
    }
}

contracts/MilestoneEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/// @title MilestoneEscrow
/// @notice Milestone-based escrow for freelance contracts on Web3LinkedIn.
///
/// @dev CRITICAL INVARIANTS (must hold after every state-changing call):
///      [I-1]  totalReleased[c] + lockedBalance[c] == fundedAmount[c]
///      [I-2]  A paid milestone can never be paid again.
///      [I-3]  The contract never pays more than milestone.amount per milestone.
///      [I-4]  Platform fee never exceeds FEE_CAP_BPS (hard-coded, 10%).
///      [I-5]  Only the client approves; only the freelancer submits.
///      [I-6]  Client cannot submit; freelancer cannot approve.
///      [I-7]  Funds in Disputed state are locked — only arbitrator can release.
///      [I-8]  Admin (DEFAULT_ADMIN_ROLE) can never touch user escrow balances.
///      [I-9]  Arbitrator can only resolve disputes — no arbitrary withdrawals.
///      [I-10] Sequential milestone enforcement: only currentMilestone is actionable.
///      [I-11] Refund returns only still-locked funds (never over-refunds).
///
/// Dispute design (centralized, clearly disclosed):
///      ARBITRATOR_ROLE is separate from DEFAULT_ADMIN_ROLE.
///      Arbitrator can only call resolveDispute() on a specific Disputed contract.
///      resolveDispute() enforces strict per-milestone accounting — it can ONLY
///      release amounts that were actually locked and not yet paid.
///
/// Token allowlist: only pre-approved tokens accepted (admin-controlled with
/// timelock in the companion TokenAllowlist contract or inline below).
contract MilestoneEscrow is AccessControlDefaultAdminRules, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    uint256 public constant FEE_CAP_BPS        = 1000;   // hard cap: 10%
    uint48  public constant FEE_TIMELOCK_DELAY  = 2 days;
    uint256 public constant MAX_MILESTONES      = 20;

    bytes32 public constant ARBITRATOR_ROLE = keccak256("ARBITRATOR_ROLE");
    bytes32 public constant PAUSER_ROLE     = keccak256("PAUSER_ROLE");
    bytes32 public constant FEE_MANAGER_ROLE = keccak256("FEE_MANAGER_ROLE");

    // -------------------------------------------------------------------------
    // State machine
    // -------------------------------------------------------------------------

    enum ContractState {
        Draft,             // created, not yet funded
        Funded,            // client deposited; work not started
        InProgress,        // freelancer started / milestone being worked on
        Submitted,         // freelancer submitted current milestone
        Completed,         // all milestones approved and paid
        Disputed,          // dispute opened, funds locked
        Cancelled,         // cancelled before funding
        Refunded           // full or partial refund issued
    }

    // -------------------------------------------------------------------------
    // Data structures
    // -------------------------------------------------------------------------

    struct Milestone {
        uint256 amount;
        bytes32 descriptionHash;   // off-chain description IPFS/Arweave hash
        bytes32 evidenceHash;      // off-chain evidence hash, set on submission
        uint64  submittedAt;
        uint64  approvedAt;
        bool    submitted;
        bool    approved;
        bool    paid;
    }

    struct EscrowContract {
        address client;
        address freelancer;
        address token;             // allowlisted ERC-20 only
        uint256 fundedAmount;      // total deposited by client
        uint256 totalReleased;     // sum of amounts paid out to freelancer
        uint256 lockedBalance;     // fundedAmount - totalReleased (updated on each payment)
        uint256 platformFeeBps;    // locked-in at creation time
        uint256 currentMilestone;
        uint256 numMilestones;
        ContractState state;
        bool disputeOpen;
    }

    uint256 private _nextContractId;
    mapping(uint256 => EscrowContract) private _contracts;
    mapping(uint256 => Milestone[]) private _milestones;

    // Accumulated platform fees per token — separate from user funds
    mapping(address => uint256) public platformFees;

    // Token allowlist
    mapping(address => bool) public allowedTokens;

    // Timelocked fee change
    struct PendingFeeChange {
        uint256 newDefaultFeeBps;
        uint64  readyAt;
        bool    pending;
    }
    PendingFeeChange public pendingFeeChange;

    uint256 public defaultPlatformFeeBps = 250; // 2.5%

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event ContractCreated(
        uint256 indexed contractId,
        address indexed client,
        address indexed freelancer,
        address token,
        uint256 totalAmount,
        uint256 numMilestones
    );
    event ContractFunded(uint256 indexed contractId, uint256 amount);
    event WorkStarted(uint256 indexed contractId);
    event MilestoneSubmitted(uint256 indexed contractId, uint256 milestoneIndex, bytes32 evidenceHash);
    event MilestoneApproved(uint256 indexed contractId, uint256 milestoneIndex, uint256 released, uint256 fee);
    event MilestoneRejected(uint256 indexed contractId, uint256 milestoneIndex);
    event DisputeOpened(uint256 indexed contractId, address indexed opener);
    event DisputeResolved(uint256 indexed contractId, uint256 toFreelancer, uint256 toClient, uint256 toFees);
    event RefundIssued(uint256 indexed contractId, uint256 amount);
    event ContractCancelled(uint256 indexed contractId);
    event PlatformFeesWithdrawn(address indexed token, address indexed to, uint256 amount);
    event FeeBpsProposed(uint256 newFeeBps, uint64 readyAt);
    event FeeBpsApplied(uint256 newFeeBps);
    event TokenAllowed(address indexed token);
    event TokenDisallowed(address indexed token);

    // -------------------------------------------------------------------------
    // Errors
    // -------------------------------------------------------------------------

    error OnlyClient();
    error OnlyFreelancer();
    error OnlyParty();
    error OnlyArbitrator();
    error TokenNotAllowed();
    error ZeroAddress();
    error ZeroAmount();
    error NoMilestones();
    error TooManyMilestones();
    error MilestoneAmountMismatch();
    error WrongState(ContractState current, ContractState expected);
    error WrongMilestone(uint256 current, uint256 provided);
    error AlreadySubmitted();
    error AlreadyPaid();
    error NotSubmitted();
    error DisputeAlreadyOpen();
    error NoDisputeOpen();
    error WorkAlreadyStarted();
    error FeeTooHigh();
    error TimelockNotExpired();
    error NoPendingChange();
    error NoFeesToWithdraw();
    error InvariantViolation();

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    constructor(uint48 adminTransferDelay, address initialAdmin)
        AccessControlDefaultAdminRules(adminTransferDelay, initialAdmin)
    {
        if (initialAdmin == address(0)) revert ZeroAddress();
        _grantRole(ARBITRATOR_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
        _grantRole(FEE_MANAGER_ROLE, initialAdmin);
    }

    // -------------------------------------------------------------------------
    // Token allowlist — admin-controlled
    // -------------------------------------------------------------------------

    function allowToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (token == address(0)) revert ZeroAddress();
        allowedTokens[token] = true;
        emit TokenAllowed(token);
    }

    function disallowToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        allowedTokens[token] = false;
        emit TokenDisallowed(token);
    }

    // -------------------------------------------------------------------------
    // Fee management — timelocked
    // -------------------------------------------------------------------------

    function proposeDefaultFeeBps(uint256 newFeeBps) external onlyRole(FEE_MANAGER_ROLE) {
        if (newFeeBps > FEE_CAP_BPS) revert FeeTooHigh();
        pendingFeeChange = PendingFeeChange({
            newDefaultFeeBps: newFeeBps,
            readyAt: uint64(block.timestamp) + FEE_TIMELOCK_DELAY,
            pending: true
        });
        emit FeeBpsProposed(newFeeBps, pendingFeeChange.readyAt);
    }

    function applyDefaultFeeBps() external onlyRole(FEE_MANAGER_ROLE) {
        PendingFeeChange memory f = pendingFeeChange;
        if (!f.pending) revert NoPendingChange();
        if (block.timestamp < f.readyAt) revert TimelockNotExpired();
        defaultPlatformFeeBps = f.newDefaultFeeBps;
        delete pendingFeeChange;
        emit FeeBpsApplied(f.newDefaultFeeBps);
    }

    // -------------------------------------------------------------------------
    // Contract lifecycle
    // -------------------------------------------------------------------------

    /// @notice Client creates a freelance contract.
    /// @param freelancer Address of the freelancer.
    /// @param token Allowlisted ERC-20 payment token.
    /// @param milestoneAmounts Per-milestone amounts (must sum to total).
    /// @param descriptionHashes Off-chain description hashes, one per milestone.
    function createContract(
        address freelancer,
        address token,
        uint256[] calldata milestoneAmounts,
        bytes32[] calldata descriptionHashes
    ) external whenNotPaused returns (uint256 contractId) {
        if (freelancer == address(0)) revert ZeroAddress();
        if (freelancer == msg.sender) revert OnlyClient();
        if (!allowedTokens[token]) revert TokenNotAllowed();
        if (milestoneAmounts.length == 0) revert NoMilestones();
        if (milestoneAmounts.length > MAX_MILESTONES) revert TooManyMilestones();
        if (milestoneAmounts.length != descriptionHashes.length) revert MilestoneAmountMismatch();

        uint256 total;
        for (uint256 i; i < milestoneAmounts.length; i++) {
            if (milestoneAmounts[i] == 0) revert ZeroAmount();
            total += milestoneAmounts[i];
        }

        contractId = _nextContractId++;
        EscrowContract storage c = _contracts[contractId];
        c.client           = msg.sender;
        c.freelancer       = freelancer;
        c.token            = token;
        c.fundedAmount     = total;  // will be validated on fund
        c.platformFeeBps   = defaultPlatformFeeBps;
        c.numMilestones    = milestoneAmounts.length;
        c.state            = ContractState.Draft;

        Milestone[] storage ms = _milestones[contractId];
        for (uint256 i; i < milestoneAmounts.length; i++) {
            ms.push(Milestone({
                amount:          milestoneAmounts[i],
                descriptionHash: descriptionHashes[i],
                evidenceHash:    bytes32(0),
                submittedAt:     0,
                approvedAt:      0,
                submitted:       false,
                approved:        false,
                paid:            false
            }));
        }

        emit ContractCreated(contractId, msg.sender, freelancer, token, total, milestoneAmounts.length);
    }

    /// @notice Client funds the contract — deposits exactly fundedAmount.
    function fundContract(uint256 contractId) external nonReentrant whenNotPaused {
        EscrowContract storage c = _requireClient(contractId);
        _requireState(c, ContractState.Draft);

        uint256 amount = c.fundedAmount;
        c.lockedBalance = amount;
        c.state = ContractState.Funded;

        IERC20(c.token).safeTransferFrom(msg.sender, address(this), amount);
        emit ContractFunded(contractId, amount);

        _checkInvariant(contractId);
    }

    /// @notice Freelancer starts work — moves state from Funded to InProgress.
    function startWork(uint256 contractId) external whenNotPaused {
        EscrowContract storage c = _requireFreelancer(contractId);
        _requireState(c, ContractState.Funded);
        c.state = ContractState.InProgress;
        emit WorkStarted(contractId);
    }

    /// @notice Freelancer submits evidence for the current milestone.
    function submitMilestone(
        uint256 contractId,
        uint256 milestoneIndex,
        bytes32 evidenceHash
    ) external whenNotPaused {
        EscrowContract storage c = _requireFreelancer(contractId);

        if (c.state != ContractState.InProgress) revert WrongState(c.state, ContractState.InProgress);
        if (milestoneIndex != c.currentMilestone) revert WrongMilestone(c.currentMilestone, milestoneIndex);

        Milestone storage m = _milestones[contractId][milestoneIndex];
        if (m.submitted) revert AlreadySubmitted();
        if (m.paid) revert AlreadyPaid();
        if (evidenceHash == bytes32(0)) revert ZeroAmount(); // evidenceHash must not be empty

        m.submitted    = true;
        m.evidenceHash = evidenceHash;
        m.submittedAt  = uint64(block.timestamp);
        c.state        = ContractState.Submitted;

        emit MilestoneSubmitted(contractId, milestoneIndex, evidenceHash);
    }

    /// @notice Client approves the submitted milestone and releases payment.
    function approveMilestone(uint256 contractId, uint256 milestoneIndex)
        external nonReentrant whenNotPaused
    {
        EscrowContract storage c = _requireClient(contractId);
        _requireState(c, ContractState.Submitted);
        if (milestoneIndex != c.currentMilestone) revert WrongMilestone(c.currentMilestone, milestoneIndex);

        Milestone storage m = _milestones[contractId][milestoneIndex];
        if (!m.submitted) revert NotSubmitted();
        if (m.paid) revert AlreadyPaid();

        uint256 fee            = (m.amount * c.platformFeeBps) / 10_000;
        uint256 toFreelancer   = m.amount - fee;

        // --- State updates before transfers (CEI pattern) ---
        m.approved    = true;
        m.paid        = true;
        m.approvedAt  = uint64(block.timestamp);
        c.totalReleased  += m.amount;
        c.lockedBalance  -= m.amount;
        platformFees[c.token] += fee;

        bool isLast = (c.currentMilestone + 1 == c.numMilestones);
        if (!isLast) {
            c.currentMilestone++;
            c.state = ContractState.InProgress;
        } else {
            c.state = ContractState.Completed;
        }

        _checkInvariant(contractId);

        // --- Transfers after state update ---
        IERC20(c.token).safeTransfer(c.freelancer, toFreelancer);
        // fee stays in contract under platformFees, not in lockedBalance

        emit MilestoneApproved(contractId, milestoneIndex, toFreelancer, fee);
    }

    /// @notice Client rejects a submitted milestone — freelancer must resubmit.
    function rejectMilestone(uint256 contractId, uint256 milestoneIndex)
        external whenNotPaused
    {
        EscrowContract storage c = _requireClient(contractId);
        _requireState(c, ContractState.Submitted);
        if (milestoneIndex != c.currentMilestone) revert WrongMilestone(c.currentMilestone, milestoneIndex);

        Milestone storage m = _milestones[contractId][milestoneIndex];
        if (!m.submitted) revert NotSubmitted();
        if (m.paid) revert AlreadyPaid();

        m.submitted    = false;
        m.evidenceHash = bytes32(0);
        m.submittedAt  = 0;
        c.state        = ContractState.InProgress;

        emit MilestoneRejected(contractId, milestoneIndex);
    }

    /// @notice Client requests a refund. Allowed only if no work has been started
    ///         (no milestone submitted or paid). If work started, client must open
    ///         a dispute instead.
    function requestRefund(uint256 contractId) external nonReentrant whenNotPaused {
        EscrowContract storage c = _requireClient(contractId);
        if (c.state != ContractState.Funded && c.state != ContractState.InProgress)
            revert WrongState(c.state, ContractState.Funded);

        // Only refundable if nothing has been submitted or paid
        Milestone[] storage ms = _milestones[contractId];
        for (uint256 i; i < ms.length; i++) {
            if (ms[i].submitted || ms[i].paid) revert WorkAlreadyStarted();
        }

        uint256 refundAmount = c.lockedBalance;
        c.lockedBalance  = 0;
        c.totalReleased  = c.fundedAmount; // accounting: fully settled
        c.state          = ContractState.Refunded;

        IERC20(c.token).safeTransfer(c.client, refundAmount);
        emit RefundIssued(contractId, refundAmount);

        _checkInvariant(contractId);
    }

    /// @notice Cancel a Draft contract (no funds deposited yet).
    function cancelContract(uint256 contractId) external whenNotPaused {
        EscrowContract storage c = _requireClient(contractId);
        _requireState(c, ContractState.Draft);
        c.state = ContractState.Cancelled;
        emit ContractCancelled(contractId);
    }

    // -------------------------------------------------------------------------
    // Dispute
    // -------------------------------------------------------------------------

    /// @notice Either party may open a dispute. Funds become locked.
    function openDispute(uint256 contractId) external whenNotPaused {
        EscrowContract storage c = _contracts[contractId];
        if (msg.sender != c.client && msg.sender != c.freelancer) revert OnlyParty();
        if (c.state == ContractState.Completed
            || c.state == ContractState.Cancelled
            || c.state == ContractState.Refunded
            || c.state == ContractState.Draft)
        {
            revert WrongState(c.state, ContractState.InProgress);
        }
        if (c.disputeOpen) revert DisputeAlreadyOpen();

        c.disputeOpen = true;
        c.state       = ContractState.Disputed;
        emit DisputeOpened(contractId, msg.sender);
    }

    /// @notice Arbitrator resolves a dispute.
    ///         `clientShareBps` = percentage (in bps, 0–10000) of the REMAINING
    ///         locked balance that goes back to client. The rest goes to freelancer
    ///         (minus platform fee on the freelancer portion).
    ///         The arbitrator can ONLY distribute the lockedBalance — it cannot
    ///         touch already-paid funds or platform fee reserves.
    function resolveDispute(uint256 contractId, uint256 clientShareBps)
        external nonReentrant onlyRole(ARBITRATOR_ROLE)
    {
        EscrowContract storage c = _contracts[contractId];
        if (c.state != ContractState.Disputed) revert NoDisputeOpen();
        if (clientShareBps > 10_000) revert FeeTooHigh();

        uint256 locked         = c.lockedBalance;
        uint256 toClient       = (locked * clientShareBps) / 10_000;
        uint256 gross          = locked - toClient;
        uint256 fee            = (gross * c.platformFeeBps) / 10_000;
        uint256 toFreelancer   = gross - fee;

        // State updates (CEI)
        c.lockedBalance      = 0;
        c.totalReleased      += locked;
        c.disputeOpen        = false;
        c.state              = ContractState.Completed;
        platformFees[c.token] += fee;

        _checkInvariant(contractId);

        // Transfers
        if (toFreelancer > 0) IERC20(c.token).safeTransfer(c.freelancer, toFreelancer);
        if (toClient      > 0) IERC20(c.token).safeTransfer(c.client,     toClient);

        emit DisputeResolved(contractId, toFreelancer, toClient, fee);
    }

    // -------------------------------------------------------------------------
    // Platform fee withdrawal — admin only, only accumulated fees
    // -------------------------------------------------------------------------

    function withdrawPlatformFees(address token, address to)
        external nonReentrant onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = platformFees[token];
        if (amount == 0) revert NoFeesToWithdraw();
        platformFees[token] = 0;
        IERC20(token).safeTransfer(to, amount);
        emit PlatformFeesWithdrawn(token, to, amount);
    }

    // -------------------------------------------------------------------------
    // Pause
    // -------------------------------------------------------------------------

    function pause()   external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    function _requireClient(uint256 id) internal view returns (EscrowContract storage c) {
        c = _contracts[id];
        if (msg.sender != c.client) revert OnlyClient();
    }

    function _requireFreelancer(uint256 id) internal view returns (EscrowContract storage c) {
        c = _contracts[id];
        if (msg.sender != c.freelancer) revert OnlyFreelancer();
    }

    function _requireState(EscrowContract storage c, ContractState expected) internal view {
        if (c.state != expected) revert WrongState(c.state, expected);
    }

    /// @dev Enforces Invariant I-1: locked + released == funded.
    ///      Reverts entire transaction if violated — fail closed.
    function _checkInvariant(uint256 contractId) internal view {
        EscrowContract storage c = _contracts[contractId];
        // Fee reserves are NOT part of lockedBalance — they live in platformFees
        // We track them inline during approveMilestone.
        // lockedBalance is decremented by full milestone.amount (fee + freelancer portion).
        // So: lockedBalance + totalReleased should always == fundedAmount.
        if (c.lockedBalance + c.totalReleased != c.fundedAmount) revert InvariantViolation();
    }

    // -------------------------------------------------------------------------
    // Views
    // -------------------------------------------------------------------------

    function getContract(uint256 contractId) external view returns (EscrowContract memory) {
        return _contracts[contractId];
    }

    function getMilestone(uint256 contractId, uint256 index)
        external view returns (Milestone memory)
    {
        return _milestones[contractId][index];
    }

    function getMilestones(uint256 contractId)
        external view returns (Milestone[] memory)
    {
        return _milestones[contractId];
    }

    function totalContracts() external view returns (uint256) {
        return _nextContractId;
    }
}

contracts/ProfileRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/// @title ProfileRegistry
/// @notice On-chain identity anchor. Stores ONLY hashes/flags, never emails,
///         names or other PII. Maps: Google account -> platform user (off-chain)
///         -> platformUserIdHash -> primary wallet -> linked wallets.
/// @dev Admin role transfer is 2-step and time-delayed (AccessControlDefaultAdminRules).
///      VERIFIER_ROLE can only grant/revoke verification badges and perform
///      platform-controlled wallet recovery — it can NEVER move funds or
///      silently take over a user's wallet identity for itself.
contract ProfileRegistry is AccessControlDefaultAdminRules, Pausable {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    struct Profile {
        bytes32 platformUserIdHash;   // hash of off-chain platform user id (never raw email)
        bytes32 profileMetadataHash;  // hash of off-chain profile JSON/bio
        bool verifiedStudent;
        bool verifiedRecruiter;
        bool exists;
    }

    mapping(address => Profile) private _profiles;       // primary wallet => profile
    mapping(bytes32 => address) public userIdToPrimary;   // platformUserIdHash => primary wallet (1:1)
    mapping(address => address) public primaryOf;         // secondary wallet => primary wallet
    mapping(address => bool) public isPrimary;
    mapping(address => uint256) public linkNonce;         // replay protection for link signatures

    event ProfileRegistered(address indexed primaryWallet, bytes32 indexed platformUserIdHash, bytes32 profileMetadataHash);
    event ProfileMetadataUpdated(address indexed primaryWallet, bytes32 newMetadataHash);
    event WalletLinked(address indexed primaryWallet, address indexed secondaryWallet);
    event WalletUnlinked(address indexed primaryWallet, address indexed secondaryWallet);
    event StudentVerified(address indexed wallet);
    event RecruiterVerified(address indexed wallet);
    event VerificationRevoked(address indexed wallet);
    event WalletRecovered(bytes32 indexed platformUserIdHash, address indexed oldPrimary, address indexed newPrimary);

    error ProfileExists();
    error ProfileNotFound();
    error ZeroAddress();
    error AlreadyLinked();
    error NotLinked();
    error InvalidSignature();
    error SelfLink();

    /// @param adminTransferDelay seconds an admin-role transfer must wait before it can be accepted (2-step, timelocked)
    constructor(uint48 adminTransferDelay, address initialAdmin)
        AccessControlDefaultAdminRules(adminTransferDelay, initialAdmin)
    {
        if (initialAdmin == address(0)) revert ZeroAddress();
        _grantRole(VERIFIER_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
    }

    // ---------------------------------------------------------------------
    // Profile registration
    // ---------------------------------------------------------------------

    function registerProfile(bytes32 platformUserIdHash, bytes32 profileMetadataHash) external whenNotPaused {
        if (_profiles[msg.sender].exists) revert ProfileExists();
        if (userIdToPrimary[platformUserIdHash] != address(0)) revert ProfileExists();

        _profiles[msg.sender] = Profile({
            platformUserIdHash: platformUserIdHash,
            profileMetadataHash: profileMetadataHash,
            verifiedStudent: false,
            verifiedRecruiter: false,
            exists: true
        });
        userIdToPrimary[platformUserIdHash] = msg.sender;
        isPrimary[msg.sender] = true;

        emit ProfileRegistered(msg.sender, platformUserIdHash, profileMetadataHash);
    }

    function updateMetadataHash(bytes32 newMetadataHash) external whenNotPaused {
        if (!_profiles[msg.sender].exists) revert ProfileNotFound();
        _profiles[msg.sender].profileMetadataHash = newMetadataHash;
        emit ProfileMetadataUpdated(msg.sender, newMetadataHash);
    }

    // ---------------------------------------------------------------------
    // Wallet linking — requires a signature FROM the new wallet proving ownership.
    // A new wallet never auto-creates a second identity.
    // ---------------------------------------------------------------------

    /// @notice Link a secondary wallet to caller's (primary) profile.
    /// @param secondary The wallet being linked.
    /// @param signature Signature by `secondary` over
    ///        keccak256(primary, secondary, nonce, address(this), "LINK")
    function linkWallet(address secondary, bytes calldata signature) external whenNotPaused {
        if (!_profiles[msg.sender].exists) revert ProfileNotFound();
        if (secondary == address(0)) revert ZeroAddress();
        if (secondary == msg.sender) revert SelfLink();
        if (primaryOf[secondary] != address(0) || isPrimary[secondary]) revert AlreadyLinked();

        uint256 nonce = linkNonce[secondary];
        bytes32 digest = keccak256(
            abi.encodePacked(msg.sender, secondary, nonce, address(this), "LINK")
        ).toEthSignedMessageHash();

        if (digest.recover(signature) != secondary) revert InvalidSignature();

        linkNonce[secondary] = nonce + 1;
        primaryOf[secondary] = msg.sender;

        emit WalletLinked(msg.sender, secondary);
    }

    /// @notice Caller (primary) unlinks one of its secondary wallets. No signature
    ///         needed from the secondary — the primary profile owner controls this.
    function unlinkWallet(address secondary) external whenNotPaused {
        if (primaryOf[secondary] != msg.sender) revert NotLinked();
        delete primaryOf[secondary];
        emit WalletUnlinked(msg.sender, secondary);
    }

    /// @notice Platform-controlled recovery: reassigns the primary wallet for a
    ///         platform user when the old wallet is lost. Off-chain identity
    ///         verification (Google re-auth / KYC) MUST gate this call before
    ///         the backend submits it. This only re-points the identity mapping —
    ///         it never moves funds and does not give the verifier custody of
    ///         anything the user owns.
    function recoverPrimaryWallet(bytes32 platformUserIdHash, address newPrimary)
        external
        onlyRole(VERIFIER_ROLE)
        whenNotPaused
    {
        if (newPrimary == address(0)) revert ZeroAddress();
        address oldPrimary = userIdToPrimary[platformUserIdHash];
        if (oldPrimary == address(0)) revert ProfileNotFound();
        if (_profiles[newPrimary].exists) revert ProfileExists();

        Profile memory p = _profiles[oldPrimary];
        delete _profiles[oldPrimary];
        isPrimary[oldPrimary] = false;

        _profiles[newPrimary] = p;
        isPrimary[newPrimary] = true;
        userIdToPrimary[platformUserIdHash] = newPrimary;

        emit WalletRecovered(platformUserIdHash, oldPrimary, newPrimary);
    }

    // ---------------------------------------------------------------------
    // Verification badges — VERIFIER_ROLE cannot touch funds or wallet links
    // ---------------------------------------------------------------------

    function verifyStudent(address wallet) external onlyRole(VERIFIER_ROLE) {
        if (!_profiles[wallet].exists) revert ProfileNotFound();
        _profiles[wallet].verifiedStudent = true;
        emit StudentVerified(wallet);
    }

    function verifyRecruiter(address wallet) external onlyRole(VERIFIER_ROLE) {
        if (!_profiles[wallet].exists) revert ProfileNotFound();
        _profiles[wallet].verifiedRecruiter = true;
        emit RecruiterVerified(wallet);
    }

    function revokeVerification(address wallet) external onlyRole(VERIFIER_ROLE) {
        if (!_profiles[wallet].exists) revert ProfileNotFound();
        _profiles[wallet].verifiedStudent = false;
        _profiles[wallet].verifiedRecruiter = false;
        emit VerificationRevoked(wallet);
    }

    // ---------------------------------------------------------------------
    // Pause (emergency stop)
    // ---------------------------------------------------------------------

    function pause() external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------

    function getProfile(address wallet) external view returns (
        bytes32 platformUserIdHash,
        bytes32 profileMetadataHash,
        bool verifiedStudent,
        bool verifiedRecruiter,
        bool exists
    ) {
        Profile storage p = _profiles[wallet];
        return (p.platformUserIdHash, p.profileMetadataHash, p.verifiedStudent, p.verifiedRecruiter, p.exists);
    }

    /// @notice Resolves any wallet (primary or secondary) to its primary wallet.
    function resolvePrimary(address wallet) external view returns (address) {
        if (isPrimary[wallet]) return wallet;
        return primaryOf[wallet];
    }
}

contracts/ProjectRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/// @title ProjectRegistry
/// @notice Immutable ownership certificates for projects. Each token = one project.
/// @dev KEY DISTINCTION (enforced by this contract):
///      - NFT ownership  ≠  copyright ownership
///      - NFT ownership  ≠  commercial license
///      - NFT ownership  ≠  exclusive license
///      - NFT ownership  ≠  full IP transfer
///      The NFT is purely an on-chain anchor proving the creator registered a
///      specific project at a specific time. What a buyer actually acquires is
///      recorded explicitly in LicenseRegistry. Transfers are intentionally
///      restricted — the project can only be transferred via the platform's
///      explicit `transferProject` function which requires an active
///      LicenseRegistry sale, preventing accidental or unauthorized transfers.
///
///      On-chain stores:
///        projectId, creator, metadataHash, repositoryCommitHash, licenseConfig,
///        createdAt, active flag.
///
///      Off-chain stores (never on-chain):
///        full description, README, videos, images, private repo URL.
contract ProjectRegistry is ERC721, AccessControlDefaultAdminRules, Pausable {

    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant PAUSER_ROLE   = keccak256("PAUSER_ROLE");

    // License types a creator can configure for their project.
    // These describe what is AVAILABLE to sell in LicenseRegistry,
    // not what is automatically transferred on NFT transfer.
    enum LicenseConfig {
        None,
        PersonalOnly,
        CommercialAvailable,
        ExclusiveAvailable,
        SourceAccessAvailable,
        FullIPTransferAvailable
    }

    struct Project {
        address creator;
        bytes32 metadataHash;        // hash of off-chain JSON (title, description, tags …)
        bytes32 repositoryCommitHash; // git commit hash anchoring a specific code version
        LicenseConfig licenseConfig;
        uint64  createdAt;
        bool    active;
        bool    metadataFrozen;      // set to true when an exclusive/IP-transfer sale is completed
    }

    uint256 private _nextProjectId;
    mapping(uint256 => Project) private _projects;

    // Track collaborators separately — they are NOT owners, only credited contributors.
    mapping(uint256 => address[]) private _collaborators;
    mapping(uint256 => mapping(address => bool)) private _isCollaborator;

    // Address of the LicenseRegistry — the ONLY contract authorised to call transferProject.
    address public licenseRegistry;

    event ProjectRegistered(
        uint256 indexed projectId,
        address indexed creator,
        bytes32 metadataHash,
        bytes32 repositoryCommitHash,
        LicenseConfig licenseConfig
    );
    event MetadataHashUpdated(uint256 indexed projectId, bytes32 newHash);
    event CommitHashUpdated(uint256 indexed projectId, bytes32 newCommitHash);
    event LicenseConfigUpdated(uint256 indexed projectId, LicenseConfig newConfig);
    event CollaboratorAdded(uint256 indexed projectId, address collaborator);
    event CollaboratorRemoved(uint256 indexed projectId, address collaborator);
    event ProjectDeactivated(uint256 indexed projectId);
    event MetadataFrozen(uint256 indexed projectId);
    event ProjectTransferred(uint256 indexed projectId, address indexed from, address indexed to);
    event LicenseRegistrySet(address licenseRegistry);

    error NotProjectOwner();
    error ProjectNotActive();
    error MetadataIsFrozen();
    error CollaboratorExists();
    error CollaboratorNotFound();
    error NotLicenseRegistry();
    error ZeroAddress();
    error AlreadySet();

    constructor(uint48 adminTransferDelay, address initialAdmin)
        ERC721("Web3LinkedInProject", "W3LPRJ")
        AccessControlDefaultAdminRules(adminTransferDelay, initialAdmin)
    {
        if (initialAdmin == address(0)) revert ZeroAddress();
        _grantRole(OPERATOR_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
    }

    // ---------------------------------------------------------------------
    // LicenseRegistry integration
    // ---------------------------------------------------------------------

    /// @notice Set once — the LicenseRegistry address that may call transferProject.
    function setLicenseRegistry(address _licenseRegistry) external onlyRole(defaultAdminRole()) {
        if (licenseRegistry != address(0)) revert AlreadySet();
        if (_licenseRegistry == address(0)) revert ZeroAddress();
        licenseRegistry = _licenseRegistry;
        emit LicenseRegistrySet(_licenseRegistry);
    }

    function defaultAdminRole() public pure returns (bytes32) {
        return DEFAULT_ADMIN_ROLE;
    }

    // ---------------------------------------------------------------------
    // Project registration
    // ---------------------------------------------------------------------

    /// @notice Register a project and mint an ownership-certificate NFT.
    function registerProject(
        bytes32 metadataHash,
        bytes32 repositoryCommitHash,
        LicenseConfig licenseConfig
    ) external whenNotPaused returns (uint256 projectId) {
        projectId = _nextProjectId++;
        _projects[projectId] = Project({
            creator: msg.sender,
            metadataHash: metadataHash,
            repositoryCommitHash: repositoryCommitHash,
            licenseConfig: licenseConfig,
            createdAt: uint64(block.timestamp),
            active: true,
            metadataFrozen: false
        });
        _safeMint(msg.sender, projectId);

        emit ProjectRegistered(projectId, msg.sender, metadataHash, repositoryCommitHash, licenseConfig);
    }

    // ---------------------------------------------------------------------
    // Owner mutations (only by current NFT holder)
    // ---------------------------------------------------------------------

    modifier onlyProjectOwner(uint256 projectId) {
        if (ownerOf(projectId) != msg.sender) revert NotProjectOwner();
        _;
    }

    modifier projectActive(uint256 projectId) {
        if (!_projects[projectId].active) revert ProjectNotActive();
        _;
    }

    modifier notFrozen(uint256 projectId) {
        if (_projects[projectId].metadataFrozen) revert MetadataIsFrozen();
        _;
    }

    function updateMetadataHash(uint256 projectId, bytes32 newHash)
        external whenNotPaused onlyProjectOwner(projectId) projectActive(projectId) notFrozen(projectId)
    {
        _projects[projectId].metadataHash = newHash;
        emit MetadataHashUpdated(projectId, newHash);
    }

    function updateCommitHash(uint256 projectId, bytes32 newCommitHash)
        external whenNotPaused onlyProjectOwner(projectId) projectActive(projectId) notFrozen(projectId)
    {
        _projects[projectId].repositoryCommitHash = newCommitHash;
        emit CommitHashUpdated(projectId, newCommitHash);
    }

    function updateLicenseConfig(uint256 projectId, LicenseConfig newConfig)
        external whenNotPaused onlyProjectOwner(projectId) projectActive(projectId) notFrozen(projectId)
    {
        _projects[projectId].licenseConfig = newConfig;
        emit LicenseConfigUpdated(projectId, newConfig);
    }

    function addCollaborator(uint256 projectId, address collaborator)
        external whenNotPaused onlyProjectOwner(projectId) projectActive(projectId)
    {
        if (collaborator == address(0)) revert ZeroAddress();
        if (_isCollaborator[projectId][collaborator]) revert CollaboratorExists();
        _collaborators[projectId].push(collaborator);
        _isCollaborator[projectId][collaborator] = true;
        emit CollaboratorAdded(projectId, collaborator);
    }

    function removeCollaborator(uint256 projectId, address collaborator)
        external whenNotPaused onlyProjectOwner(projectId) projectActive(projectId)
    {
        if (!_isCollaborator[projectId][collaborator]) revert CollaboratorNotFound();
        _isCollaborator[projectId][collaborator] = false;
        address[] storage colabs = _collaborators[projectId];
        for (uint256 i = 0; i < colabs.length; i++) {
            if (colabs[i] == collaborator) {
                colabs[i] = colabs[colabs.length - 1];
                colabs.pop();
                break;
            }
        }
        emit CollaboratorRemoved(projectId, collaborator);
    }

    function deactivateProject(uint256 projectId)
        external whenNotPaused onlyProjectOwner(projectId)
    {
        _projects[projectId].active = false;
        emit ProjectDeactivated(projectId);
    }

    // ---------------------------------------------------------------------
    // Transfer — ONLY callable by LicenseRegistry after a completed IP-transfer sale.
    // Normal ERC-721 safeTransferFrom / transferFrom are BLOCKED to prevent
    // accidental or marketplace-bypass transfers.
    // ---------------------------------------------------------------------

    function transferProject(uint256 projectId, address to) external whenNotPaused {
        if (msg.sender != licenseRegistry) revert NotLicenseRegistry();
        if (to == address(0)) revert ZeroAddress();
        address from = ownerOf(projectId);
        _transfer(from, to, projectId);
        emit ProjectTransferred(projectId, from, to);
    }

    /// @dev Block all ERC-721 standard transfers so the NFT can ONLY move
    ///      through transferProject (called by LicenseRegistry).
    function transferFrom(address, address, uint256) public pure override {
        revert NotLicenseRegistry();
    }

    function safeTransferFrom(address, address, uint256, bytes memory) public pure override {
        revert NotLicenseRegistry();
    }

    // ---------------------------------------------------------------------
    // Metadata freeze — called by LicenseRegistry on ExclusiveAvailable / FullIP sales
    // ---------------------------------------------------------------------

    function freezeMetadata(uint256 projectId) external {
        if (msg.sender != licenseRegistry) revert NotLicenseRegistry();
        _projects[projectId].metadataFrozen = true;
        emit MetadataFrozen(projectId);
    }

    // ---------------------------------------------------------------------
    // Pause
    // ---------------------------------------------------------------------

    function pause() external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------

    function getProject(uint256 projectId) external view returns (
        address creator,
        bytes32 metadataHash,
        bytes32 repositoryCommitHash,
        LicenseConfig licenseConfig,
        uint64 createdAt,
        bool active,
        bool metadataFrozen,
        address currentOwner
    ) {
        Project storage p = _projects[projectId];
        return (
            p.creator,
            p.metadataHash,
            p.repositoryCommitHash,
            p.licenseConfig,
            p.createdAt,
            p.active,
            p.metadataFrozen,
            ownerOf(projectId)
        );
    }

    function getCollaborators(uint256 projectId) external view returns (address[] memory) {
        return _collaborators[projectId];
    }

    function isCollaborator(uint256 projectId, address wallet) external view returns (bool) {
        return _isCollaborator[projectId][wallet];
    }

    function totalProjects() external view returns (uint256) {
        return _nextProjectId;
    }

    // Required override — both parents define supportsInterface
    function supportsInterface(bytes4 interfaceId)
        public view override(ERC721, AccessControlDefaultAdminRules)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/ReferralRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/// @title ReferralRegistry
/// @notice MVP referral tracking. Records who referred whom and what qualifying
///         event triggered the referral.
///
/// @dev No token rewards in this version (spec: "handle later after legal and
///      economic review"). Only records, no fund transfers.
///      REGISTRAR_ROLE is assigned to the backend service that validates events.
contract ReferralRegistry is AccessControlDefaultAdminRules, Pausable {

    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant PAUSER_ROLE    = keccak256("PAUSER_ROLE");

    struct Referral {
        address referrer;
        address referee;
        bytes32 sourceHash;    // hash of referral source/campaign (off-chain)
        bytes32 eventHash;     // hash of qualifying event data (off-chain)
        uint64  timestamp;
        bool    rewarded;      // toggled by admin when reward is distributed off-chain
    }

    uint256 private _nextReferralId;
    mapping(uint256 => Referral) private _referrals;

    // Prevent duplicate referrals between the same pair
    mapping(address => mapping(address => bool)) public hasReferred;

    // Per-referrer count
    mapping(address => uint256) public referralCount;

    event ReferralRecorded(
        uint256 indexed referralId,
        address indexed referrer,
        address indexed referee,
        bytes32 sourceHash,
        bytes32 eventHash
    );
    event ReferralRewarded(uint256 indexed referralId);

    error SelfReferral();
    error AlreadyReferred();
    error AlreadyRewarded();
    error NotFound();
    error ZeroAddress();

    constructor(uint48 adminTransferDelay, address initialAdmin)
        AccessControlDefaultAdminRules(adminTransferDelay, initialAdmin)
    {
        if (initialAdmin == address(0)) revert ZeroAddress();
        _grantRole(REGISTRAR_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
    }

    function recordReferral(
        address referrer,
        address referee,
        bytes32 sourceHash,
        bytes32 eventHash
    ) external onlyRole(REGISTRAR_ROLE) whenNotPaused returns (uint256 referralId) {
        if (referrer == address(0) || referee == address(0)) revert ZeroAddress();
        if (referrer == referee) revert SelfReferral();
        if (hasReferred[referrer][referee]) revert AlreadyReferred();

        referralId = _nextReferralId++;
        _referrals[referralId] = Referral({
            referrer:   referrer,
            referee:    referee,
            sourceHash: sourceHash,
            eventHash:  eventHash,
            timestamp:  uint64(block.timestamp),
            rewarded:   false
        });
        hasReferred[referrer][referee] = true;
        referralCount[referrer]++;

        emit ReferralRecorded(referralId, referrer, referee, sourceHash, eventHash);
    }

    function markRewarded(uint256 referralId) external onlyRole(DEFAULT_ADMIN_ROLE) {
        Referral storage r = _referrals[referralId];
        if (r.referrer == address(0)) revert NotFound();
        if (r.rewarded) revert AlreadyRewarded();
        r.rewarded = true;
        emit ReferralRewarded(referralId);
    }

    function pause()   external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    function getReferral(uint256 id) external view returns (Referral memory) {
        return _referrals[id];
    }

    function totalReferrals() external view returns (uint256) {
        return _nextReferralId;
    }
}

contracts/ReputationAttestation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/// @title ReputationAttestation
/// @notice Records verifiable work events as immutable on-chain attestations.
///
/// @dev The spec explicitly forbids a mutable "trust score" as the source of truth.
///      Instead, this contract records individual events that the frontend/backend
///      aggregates for display. Each attestation is:
///        - Tied to a specific contractId (from MilestoneEscrow)
///        - Submitted once per contract per direction (client->freelancer or reverse)
///        - Immutable after submission
///        - Linked to the actual contract parties (verified off-chain by backend
///          before calling attest())
///
///      Rating content (text comments, star displays) stays off-chain.
///      On-chain: who rated whom, for which contract, what event type, metadata hash.
///
///      ATTESTER_ROLE is assigned to a trusted backend service that verifies the
///      contract is actually completed before submitting an attestation.
///      Admin (DEFAULT_ADMIN_ROLE) CANNOT edit/delete attestations once made —
///      append-only by design.
contract ReputationAttestation is AccessControlDefaultAdminRules, Pausable {

    bytes32 public constant ATTESTER_ROLE = keccak256("ATTESTER_ROLE");
    bytes32 public constant PAUSER_ROLE   = keccak256("PAUSER_ROLE");

    enum EventType {
        ContractCompleted,       // 0
        MilestoneApproved,       // 1
        ProjectLicensed,         // 2
        ClientRatingSubmitted,   // 3  — client rated the freelancer
        FreelancerRatingSubmitted, // 4 — freelancer rated the client
        DisputeResolved          // 5
    }

    /// @notice A single verifiable event.
    /// @param contractId  On-chain contract id in MilestoneEscrow (or 0 if N/A).
    /// @param attester    Who submitted this attestation (ATTESTER_ROLE holder).
    /// @param subject     The wallet being attested about.
    /// @param rater       The wallet providing the rating/attestation.
    /// @param eventType   Type of event.
    /// @param metadataHash Hash of off-chain metadata (rating score, comment hash, IPFS link).
    /// @param timestamp   Block timestamp.
    struct Attestation {
        uint256  contractId;
        address  attester;
        address  subject;
        address  rater;
        EventType eventType;
        bytes32  metadataHash;
        uint64   timestamp;
    }

    uint256 private _nextAttestationId;
    mapping(uint256 => Attestation) private _attestations;

    // Prevent double-rating: contractId + rater + direction → already rated
    mapping(uint256 => mapping(address => bool)) public hasRated;

    // Per-wallet summary counters (append-only, never decremented)
    struct WalletStats {
        uint256 completedContracts;
        uint256 approvedMilestones;
        uint256 totalLicenses;
        uint256 disputesResolved;
        uint256 ratingsReceived;
    }
    mapping(address => WalletStats) private _stats;

    event AttestationRecorded(
        uint256 indexed attestationId,
        uint256 indexed contractId,
        address indexed subject,
        address rater,
        EventType eventType,
        bytes32 metadataHash
    );

    error ZeroAddress();
    error AlreadyRated();
    error InvalidEvent();

    constructor(uint48 adminTransferDelay, address initialAdmin)
        AccessControlDefaultAdminRules(adminTransferDelay, initialAdmin)
    {
        if (initialAdmin == address(0)) revert ZeroAddress();
        _grantRole(ATTESTER_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
    }

    // -------------------------------------------------------------------------
    // Core attestation — called by ATTESTER_ROLE (trusted backend service)
    // -------------------------------------------------------------------------

    /// @notice Record a verifiable event.
    /// @param contractId  MilestoneEscrow contractId (0 if not contract-related).
    /// @param subject     Wallet being evaluated.
    /// @param rater       Wallet providing the evaluation (actual contract party).
    /// @param eventType   Type of event.
    /// @param metadataHash Hash of off-chain rating data.
    function attest(
        uint256   contractId,
        address   subject,
        address   rater,
        EventType eventType,
        bytes32   metadataHash
    ) external onlyRole(ATTESTER_ROLE) whenNotPaused returns (uint256 attestationId) {
        if (subject == address(0)) revert ZeroAddress();
        if (rater  == address(0)) revert ZeroAddress();

        // Ratings (client→freelancer, freelancer→client) are one per contract per rater.
        if (
            eventType == EventType.ClientRatingSubmitted
            || eventType == EventType.FreelancerRatingSubmitted
        ) {
            if (hasRated[contractId][rater]) revert AlreadyRated();
            hasRated[contractId][rater] = true;
        }

        attestationId = _nextAttestationId++;
        _attestations[attestationId] = Attestation({
            contractId:   contractId,
            attester:     msg.sender,
            subject:      subject,
            rater:        rater,
            eventType:    eventType,
            metadataHash: metadataHash,
            timestamp:    uint64(block.timestamp)
        });

        // Update summary counters
        WalletStats storage st = _stats[subject];
        if (eventType == EventType.ContractCompleted)         st.completedContracts++;
        else if (eventType == EventType.MilestoneApproved)    st.approvedMilestones++;
        else if (eventType == EventType.ProjectLicensed)      st.totalLicenses++;
        else if (eventType == EventType.DisputeResolved)      st.disputesResolved++;
        else if (
            eventType == EventType.ClientRatingSubmitted
            || eventType == EventType.FreelancerRatingSubmitted
        )                                                       st.ratingsReceived++;

        emit AttestationRecorded(attestationId, contractId, subject, rater, eventType, metadataHash);
    }

    // -------------------------------------------------------------------------
    // Pause
    // -------------------------------------------------------------------------

    function pause()   external onlyRole(PAUSER_ROLE) { _pause(); }
    function unpause() external onlyRole(PAUSER_ROLE) { _unpause(); }

    // -------------------------------------------------------------------------
    // Views — read-only, no mutation
    // -------------------------------------------------------------------------

    function getAttestation(uint256 id) external view returns (Attestation memory) {
        return _attestations[id];
    }

    /// @notice Returns append-only summary stats. NOT a mutable trust score.
    ///         Frontend/backend should aggregate individual attestations for full picture.
    function getStats(address wallet) external view returns (WalletStats memory) {
        return _stats[wallet];
    }

    function totalAttestations() external view returns (uint256) {
        return _nextAttestationId;
    }
}

